/** The clickable zone names, in no particular order. */
export const ZONES = ['sole', 'upper', 'laces'];

/**
 * Build a scene with three clickable zone meshes:
 * - "sole":  flat box spanning y 0..0.3 (2.0 x 0.3 x 4.0), centered at origin
 * - "upper": box spanning y 0.3..1.0 (1.4 x 0.7 x 1.8), centered at origin
 * - "laces": thin box sitting on top-front of the upper
 *
 * Sizes are chosen so that, with a PerspectiveCamera (fov 50, aspect 1) at
 * (0, 0.6, 5) looking at the origin:
 * - a ray through ndc (0, -0.4) cleanly hits the sole's front face
 * - a ray through ndc (0, 0.1) cleanly hits the upper's front face
 * - a ray through ndc (0.95, 0.95) exits past every box (returns null)
 */
export function buildShoeScene() {
  const scene = new THREE.Scene();

  const addZone = (name, width, height, depth, position, hex) => {
    const geometry = new THREE.BoxGeometry(width, height, depth);
    const material = new THREE.MeshBasicMaterial({ color: hex });
    const mesh = new THREE.Mesh(geometry, material);
    mesh.name = name;
    mesh.position.set(...position);
    scene.add(mesh);
    return mesh;
  };

  // sole: wide and deep so the downward ray lands on its front face well inside it
  addZone('sole', 2.0, 0.3, 4.0, [0, 0.15, 0], 0xdddddd);
  // upper: sits directly on top of the sole (y 0.3..1.0)
  addZone('upper', 1.4, 0.7, 1.8, [0, 0.65, 0], 0x888888);
  // laces: thin slab resting on top of the upper, toward its front edge
  addZone('laces', 0.8, 0.12, 0.6, [0, 1.06, 0.45], 0x333333);

  return scene;
}

/**
 * Cast a ray from the camera through the given NDC coordinates and return
 * the name of the first zone mesh hit, or null if nothing was hit.
 * Purely read-only: never mutates the scene.
 */
export function pickZone(scene, camera, ndcX, ndcY) {
  const raycaster = new THREE.Raycaster();
  raycaster.setFromCamera(new THREE.Vector2(ndcX, ndcY), camera);

  const zoneMeshes = ZONES.map((name) => scene.getObjectByName(name)).filter(Boolean);
  const hits = raycaster.intersectObjects(zoneMeshes, false);

  return hits.length > 0 ? hits[0].object.name : null;
}

/**
 * Set the material color of the named zone mesh.
 * Throws if the zone does not exist.
 */
export function applyColor(scene, zone, hex) {
  const mesh = scene.getObjectByName(zone);
  if (!mesh) throw new Error(`Unknown zone: ${zone}`);
  mesh.material.color.setHex(hex);
}
"})
