result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test/picker.test.js", "content": "import { describe, it, expect } from 'vitest';
import * as THREE from 'three';
import { buildShoeScene, pickZone, applyColor, ZONES } from '../src/picker.js';

/** PerspectiveCamera at (0, 0.6, 5) looking at the origin, matrices updated. */
function makeCamera() {
  const camera = new THREE.PerspectiveCamera(50, 1, 0.1, 100);
  camera.position.set(0, 0.6, 5);
  camera.lookAt(0, 0, 0);
  camera.updateMatrixWorld(true);
  return camera;
}

/** Plain-JSON snapshot of everything pickZone is allowed to touch. */
function snapshot(scene) {
  const state = {};
  for (const name of ZONES) {
    const mesh = scene.getObjectByName(name);
    state[name] = {
      position: mesh.position.toArray(),
      quaternion: mesh.quaternion.toArray(),
      scale: mesh.scale.toArray(),
      color: '#' + mesh.material.color.getHexString(),
    };
  }
  return JSON.parse(JSON.stringify(state));
}

describe('buildShoeScene', () => {
  it('contains exactly the three zone meshes with the specified vertical extents', () => {
    const scene = buildShoeScene();
    expect(scene.children.map((c) => c.name).sort()).toEqual(['laces', 'sole', 'upper']);

    for (const name of ZONES) {
      const mesh = scene.getObjectByName(name);
      expect(mesh).toBeInstanceOf(THREE.Mesh);
      mesh.geometry.computeBoundingBox();
    }

    const box = (name) => scene.getObjectByName(name).geometry.boundingBox;

    // sole: flat box spanning y 0..0.3
    expect(box('sole').min.y).toBeCloseTo(0, 5);
    expect(box('sole').max.y).toBeCloseTo(0.3, 5);

    // upper: box spanning y 0.3..1
    expect(box('upper').min.y).toBeCloseTo(0.3, 5);
    expect(box('upper').max.y).toBeCloseTo(1.0, 5);

    // laces: thin box resting on top of the upper, toward the front
    const lacesSize = new THREE.Vector3();
    scene.getObjectByName('laces').geometry.boundingBox.getSize(lacesSize);
    expect(lacesSize.y).toBeLessThan(0.2);
    expect(scene.getObjectByName('laces').position.z).toBeGreaterThan(0);
  });
});

describe('pickZone', () => {
  const scene = buildShoeScene();
  const camera = makeCamera();

  it('a ray through ndc (0, -0.4) hits the "sole"', () => {
    expect(pickZone(scene, camera, 0, -0.4)).toBe('sole');
  });

  it('a ray through ndc (0, 0.1) hits the "upper"', () => {
    expect(pickZone(scene, camera, 0, 0.1)).toBe('upper');
  });

  it('a ray through the corner ndc (0.95, 0.95) hits nothing', () => {
    expect(pickZone(scene, camera, 0.95, 0.95)).toBeNull();
  });

  it('is deterministic across repeated picks', () => {
    expect(pickZone(scene, camera, 0, -0.4)).toBe('sole');
    expect(pickZone(scene, camera, 0, -0.4)).toBe('sole');
    expect(pickZone(scene, camera, 0, 0.1)).toBe('upper');
  });

  it('never mutates the scene', () => {
    const fresh = buildShoeScene();
    const cam = makeCamera();
    const before = snapshot(fresh);

    pickZone(fresh, cam, 0, -0.4);
    pickZone(fresh, cam, 0, 0.1);
    pickZone(fresh, cam, 0.95, 0.95);

    expect(snapshot(fresh)).toEqual(before);
  });
});

describe('applyColor', () => {
  it('changes only the target zone\'s color', () => {
    const scene = buildShoeScene();

    applyColor(scene, 'upper', 0xff2200);

    expect('#' + scene.getObjectByName('upper').material.color.getHexString()).toBe('#ff2200');
    // others keep their original colors
    expect('#' + scene.getObjectByName('sole').material.color.getHexString()).toBe('#dddddd');
    expect('#' + scene.getObjectByName('laces').material.color.getHexString()).toBe('#333333');
  });

  it('works on each zone independently', () => {
    const scene = buildShoeScene();

    applyColor(scene, 'sole', 0x00ff00);
    applyColor(scene, 'laces', 0x0000ff);

    expect(pickZone(scene, makeCamera(), 0, -0.4)).toBe('sole');
    expect(pickZone(scene, makeCamera(), 0, 0.1)).toBe('upper');
    expect('#' + scene.getObjectByName('sole').material.color.getHexString()).toBe('#00ff00');
    expect('#' + scene.getObjectByName('laces').material.color.getHexString()).toBe('#0000ff');
  });

  it('throws for an unknown zone', () => {
    const scene = buildShoeScene();
    expect(() => applyColor(scene, 'heel', 0xff0000)).toThrow(/Unknown zone/);
  });
});
"})
